using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using Staybnb.Data; using Staybnb.Models; using Staybnb.Services; using Staybnb.ViewModels;
namespace Staybnb.Controllers;
[Authorize(Roles="Guest")]
public class HostApplicationsController(ApplicationDbContext db,UserManager<ApplicationUser> users,SecureFileStorage storage,ActivityLogger logger,NotificationService notifications):Controller {
 [HttpGet] public async Task<IActionResult> Create(){var uid=users.GetUserId(User)!;if(await db.HostApplications.AnyAsync(a=>a.ApplicationUserId==uid&&a.Status==WorkflowStatus.Pending))return RedirectToAction(nameof(MyApplication));return View(new PropertyApplicationViewModel());}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Create(PropertyApplicationViewModel vm){if(vm.Images==null||vm.Images.Count==0)ModelState.AddModelError(nameof(vm.Images),"Upload at least one property image.");if(!ModelState.IsValid)return View(vm);var uid=users.GetUserId(User)!;if(await db.HostApplications.AnyAsync(a=>a.ApplicationUserId==uid&&a.Status==WorkflowStatus.Pending)) {ModelState.AddModelError("","You already have a pending application.");return View(vm);}var p=new HostProperty{UserId=uid,Title=vm.Title,Description=vm.Description,PricePerNight=vm.PricePerNight,CleaningFee=vm.CleaningFee,ServiceFee=vm.ServiceFee,Capacity=vm.Capacity,Address=vm.Address,City=vm.City,PropertyType=vm.PropertyType,IsActive=false};try{foreach(var image in vm.Images){var url=await storage.SavePropertyImageAsync(image);p.Images.Add(new PropertyImage{ImageUrl=url,IsPrimary=p.Images.Count==0});}}catch(InvalidOperationException ex){ModelState.AddModelError(nameof(vm.Images),ex.Message);return View(vm);}var app=new HostApplication{ApplicationUserId=uid,Property=p,Status=WorkflowStatus.Pending};db.HostApplications.Add(app);await db.SaveChangesAsync();await logger.LogAsync(uid,"Submitted Host application #"+app.Id,"HostApplication");await notifications.AddAsync(uid,"Your Host application has been submitted","HostApplication","/HostApplications/MyApplication");return RedirectToAction(nameof(MyApplication));}
 [HttpGet] public async Task<IActionResult> MyApplication(){var uid=users.GetUserId(User)!;return View(await db.HostApplications.Include(a=>a.Property!).ThenInclude(p=>p.Images).Where(a=>a.ApplicationUserId==uid).OrderByDescending(a=>a.AppliedAt).ToListAsync());}
}
